drop table if exists operation_log; drop table if exists repair_order; drop table if exists reservation; drop table if exists device; drop table if exists lab_admin_assignment; drop table if exists lab; drop table if exists sys_user;
create table sys_user(id bigint auto_increment primary key,username varchar(50) unique not null,password_hash varchar(120) not null,real_name varchar(50),phone varchar(30),role varchar(30) not null,status int default 1);
create table lab(id bigint auto_increment primary key,name varchar(100) not null,location varchar(150),capacity int,manager varchar(50),phone varchar(30),description varchar(500),open_time varchar(10),close_time varchar(10),open_status int default 1);
create table lab_admin_assignment(user_id bigint not null,lab_id bigint not null,primary key(user_id,lab_id),constraint uq_lab_admin_assignment_lab unique(lab_id),constraint fk_lab_admin_user foreign key(user_id) references sys_user(id),constraint fk_lab_admin_lab foreign key(lab_id) references lab(id));
create table device(id bigint auto_increment primary key,device_code varchar(50) unique not null,name varchar(100) not null,category varchar(50),model varchar(100),lab_id bigint,purchase_date date,status varchar(30),remark varchar(500),foreign key(lab_id) references lab(id));
create table reservation(id bigint auto_increment primary key,applicant_id bigint not null,lab_id bigint not null,reserve_date date not null,start_time time not null,end_time time not null,purpose varchar(255),participants int,remark varchar(500),status varchar(30),reject_reason varchar(500),auditor_id bigint,audit_time timestamp,created_at timestamp default current_timestamp,foreign key(applicant_id) references sys_user(id),foreign key(lab_id) references lab(id));
create table repair_order(id bigint auto_increment primary key,device_id bigint not null,reporter_id bigint not null,handler_id bigint,fault_desc varchar(500),severity varchar(30),remark varchar(500),status varchar(30),result varchar(500),created_at timestamp default current_timestamp,completed_at timestamp,foreign key(device_id) references device(id));
create table operation_log(id bigint auto_increment primary key,operator_id bigint,module varchar(50),action varchar(100),result varchar(30),created_at timestamp default current_timestamp);
